Python async pager + batch example:
from redwood import Client
client = Client(api_key="***")
async def pipeline():
    pager = client.vectors.pager(query='user-history', page_size=500)
    async for batch in pager.async_batches(batch_size=256):
        resp = await client.rerank.call_batch(batch_items=batch, retry_policy=client.RetryPolicy.default())
        # handle partial stream aggregation
TypeScript async generator + batch builder:
const client = new RedwoodClient({apiKey: process.env.RW_KEY});
async function pipeline(){
  for await (const batch of client.vectors.pager({query: 'user-history', pageSize: 500}).batches(256)) {
    const out = await client.rerank.callBatch({items: batch});
  }
}
